import 'package:flutter/material.dart';
import 'package:google_sign_in/google_sign_in.dart';
import 'nexora_chat_service.dart';
class NexoraChatPage extends StatefulWidget { final GoogleSignInAccount account; const NexoraChatPage({required this.account,super.key}); @override State<NexoraChatPage> createState()=>_NexoraChatPageState(); }
class _NexoraChatPageState extends State<NexoraChatPage>{
 final service=NexoraChatService.instance; bool loading=true; String? error;
 @override void initState(){super.initState();_init();}
 Future<void> _init() async {await service.initialize(widget.account);if(!mounted)return;setState(()=>loading=false);if(service.error!=null)setState(()=>error=service.error);}
 Future<void> _search() async {final ctrl=TextEditingController();final user=await showDialog<Map<String,dynamic>>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Cari teman'),content:TextField(controller:ctrl,autofocus:true,decoration:const InputDecoration(hintText:'Email pengguna Nexora')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Batal')),FilledButton(onPressed:() async {try{final users=await service.searchUsers(ctrl.text);if(ctx.mounted)Navigator.pop(ctx,users.isEmpty?null:users.first);}catch(_){if(ctx.mounted)Navigator.pop(ctx);}},child:const Text('Cari'))]));if(user==null||!mounted)return;try{final id=await service.openConversation(user['id'].toString());if(!mounted)return;Navigator.push(context,MaterialPageRoute(builder:(_)=>_NexoraConversation(service:service,id:id,title:user['display_name']?.toString()??user['email'].toString())));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Tidak bisa membuka chat: $e')));}}
 @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.cloud_off_rounded,size:52),const SizedBox(height:12),const Text('Chat belum tersambung',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(error!,textAlign:TextAlign.center),const SizedBox(height:14),const Text('Jalankan supabase/schema.sql di SQL Editor project Nexora setelah memasukkan konfigurasi build.',textAlign:TextAlign.center,style:TextStyle(color:Colors.white60,fontSize:12)),const SizedBox(height:12),FilledButton(onPressed:() async {setState(()=>loading=true);await _init();},child:const Text('Coba lagi'))])));return Column(children:[Padding(padding:const EdgeInsets.fromLTRB(18,16,18,8),child:Row(children:[const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Nexora Chat',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),Text('Pesan pribadi tersinkronisasi',style:TextStyle(color:Colors.white60))])),IconButton(onPressed:_search,icon:const Icon(Icons.person_add_alt_1_rounded))])),Expanded(child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.forum_outlined,size:58,color:Colors.white38),const SizedBox(height:12),const Text('Mulai percakapan',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('Cari email teman Nexora untuk mengirim pesan.',style:TextStyle(color:Colors.white60)),const SizedBox(height:16),FilledButton.icon(onPressed:_search,icon:const Icon(Icons.search),label:const Text('Cari pengguna'))]))) ]);}
}
class _NexoraConversation extends StatefulWidget {final NexoraChatService service;final String id,title;const _NexoraConversation({required this.service,required this.id,required this.title});@override State<_NexoraConversation> createState()=>_NexoraConversationState();}
class _NexoraConversationState extends State<_NexoraConversation>{final input=TextEditingController();bool sending=false;@override void dispose(){input.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.title)),body:Column(children:[Expanded(child:StreamBuilder<List<Map<String,dynamic>>>(stream:widget.service.messageStream(widget.id),builder:(context,snap){if(snap.hasError)return Center(child:Text('Gagal memuat pesan: ${snap.error}'));if(!snap.hasData)return const Center(child:CircularProgressIndicator());final me=widget.service.client!.auth.currentUser!.id;final rows=snap.data!;if(rows.isEmpty)return const Center(child:Text('Kirim pesan pertama kamu.'));return ListView.builder(padding:const EdgeInsets.all(14),itemCount:rows.length,itemBuilder:(context,i){final row=rows[i];final mine=row['sender_id']==me;return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:300),margin:const EdgeInsets.symmetric(vertical:4),padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),decoration:BoxDecoration(color:mine?Theme.of(context).colorScheme.primary:const Color(0xFF202638),borderRadius:BorderRadius.circular(16)),child:Text(row['body']?.toString()??'')));});})),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:input,minLines:1,maxLines:4,decoration:const InputDecoration(hintText:'Tulis pesan...',border:OutlineInputBorder(),contentPadding:EdgeInsets.symmetric(horizontal:14,vertical:10)))),const SizedBox(width:8),IconButton.filled(onPressed:sending?null:() async {final text=input.text;if(text.trim().isEmpty)return;setState(()=>sending=true);try{await widget.service.send(widget.id,text);input.clear();}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Pesan gagal dikirim: $e')));}if(mounted)setState(()=>sending=false);},icon:const Icon(Icons.send_rounded))])))]));}
